-- Declared foreign keys for blog module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('blog.posts') IS NOT NULL AND to_regclass('blog.blogs') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('blog.posts') AND c.contype = 'f' AND a.attname = 'blog_id'
    ) THEN
        ALTER TABLE blog.posts ADD CONSTRAINT fk_posts_blog_id FOREIGN KEY (blog_id) REFERENCES blog.blogs (id) NOT VALID;
        BEGIN
            ALTER TABLE blog.posts VALIDATE CONSTRAINT fk_posts_blog_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_posts_blog_id left NOT VALID: stored rows of blog.posts reference missing rows';
        END;
    END IF;
END $$;

